<div class="interactive-wrapper"><div class="card shadow-sm border-0 mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#eef2ff"><i class="fas fa-atom text-primary"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Chemical Element Lookup</h5><p class="text-muted small mb-0">Look up element properties, electron configuration</p></div></div><button class="btn btn-sm rounded-pill px-3" id="btn-reset" style="background:#f1f5f9;font-weight:600"><i class="fas fa-undo me-1"></i>Reset</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="row g-3"><div class="col-12"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Element Symbol or Name</label><input type="text" id="in-el" class="form-control form-control-lg" value="Carbon" placeholder="e.g. Carbon, Fe, 26"></div></div><div class="mt-4 text-center"><button class="btn btn-primary btn-lg rounded-pill px-5 shadow-sm" id="btn-calc" style="min-width:260px;max-width:100%"><i class="fas fa-calculator me-2"></i>Calculate</button></div><div class="mt-3 p-3 rounded-4 border" style="background:#f8fafc"><p class="mb-0 small text-muted"><i class="fas fa-info-circle text-primary me-2"></i><b>Source:</b> IUPAC Periodic Table 2021</p></div></div></div><div id="res" class="card shadow-sm border-0 d-none mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#ecfdf5"><i class="fas fa-check-circle text-success"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Result</h5></div></div><button class="btn btn-success btn-sm rounded-pill px-4 shadow-sm" id="btn-copy"><i class="fas fa-copy me-1"></i>Copy</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="p-4 rounded-4 bg-light border text-center mb-3"><div class="small fw-bold text-uppercase text-muted mb-1">RESULT</div><div class="display-4 fw-bold text-dark" id="out-main">—</div><div class="small text-muted fw-bold" id="out-unit"></div></div><div id="out-detail" class="row g-3 mb-3"></div><div class="p-4 rounded-4 bg-light border"><h6 class="fw-bold mb-2 small text-uppercase text-muted"><i class="fas fa-lightbulb text-warning me-2"></i>Insights</h6><div id="out-ins" class="small"></div></div></div></div></div><style>.form-control-lg,.form-select-lg{border:1.5px solid #e2e8f0;border-radius:12px;font-size:1.05rem;padding:.75rem 1rem}.form-control:focus,.form-select:focus{border-color:#4f46e5;box-shadow:0 0 0 4px rgba(79,70,229,.1)}</style><script>document.addEventListener("DOMContentLoaded",function(){var DB={H:{z:1,w:1.008,name:"Hydrogen",ec:"1s1",g:"Nonmetal"},He:{z:2,w:4.003,name:"Helium",ec:"1s2",g:"Noble gas"},Li:{z:3,w:6.941,name:"Lithium",ec:"[He]2s1",g:"Alkali metal"},C:{z:6,w:12.011,name:"Carbon",ec:"[He]2s2 2p2",g:"Nonmetal"},N:{z:7,w:14.007,name:"Nitrogen",ec:"[He]2s2 2p3",g:"Nonmetal"},O:{z:8,w:15.999,name:"Oxygen",ec:"[He]2s2 2p4",g:"Nonmetal"},Na:{z:11,w:22.990,name:"Sodium",ec:"[Ne]3s1",g:"Alkali metal"},Cl:{z:17,w:35.45,name:"Chlorine",ec:"[Ne]3s2 3p5",g:"Halogen"},Fe:{z:26,w:55.845,name:"Iron",ec:"[Ar]3d6 4s2",g:"Transition metal"},Cu:{z:29,w:63.546,name:"Copper",ec:"[Ar]3d10 4s1",g:"Transition metal"},Au:{z:79,w:196.97,name:"Gold",ec:"[Xe]4f14 5d10 6s1",g:"Transition metal"},Ag:{z:47,w:107.87,name:"Silver",ec:"[Kr]4d10 5s1",g:"Transition metal"}};function find(q){q=q.trim();for(var k in DB){if(k.toLowerCase()===q.toLowerCase()||DB[k].name.toLowerCase()===q.toLowerCase()||DB[k].z===parseInt(q))return{sym:k,d:DB[k]};}return null;}document.getElementById("btn-calc").addEventListener("click",function(){var r=find(document.getElementById("in-el").value);if(!r){document.getElementById("out-main").textContent="Not found";document.getElementById("out-unit").textContent="Try another element";document.getElementById("out-detail").innerHTML="";document.getElementById("out-ins").innerHTML="";document.getElementById("res").classList.remove("d-none");return;}document.getElementById("out-main").textContent=r.sym+" — "+r.d.name;document.getElementById("out-main").style.fontSize="2rem";document.getElementById("out-unit").textContent=r.d.g;document.getElementById("out-detail").innerHTML='<div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Atomic #</div><div class="h5 fw-bold mb-0 text-primary">'+r.d.z+'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Weight</div><div class="h5 fw-bold mb-0 text-info">'+r.d.w+' u</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Config</div><div class="h5 fw-bold mb-0 text-success" style="font-size:0.85rem">'+r.d.ec+'</div></div></div>';document.getElementById("out-ins").innerHTML="<p>Electron config: <b>"+r.d.ec+"</b></p>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-el").value="Carbon";document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText(document.getElementById("out-main").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\"fas fa-copy me-1\"></i>Copy";},2e3);});});</script><?php /**PATH D:\Xamp\htdocs\ToolsHub\resources\views\tools\interactive\chemical-element-lookup.blade.php ENDPATH**/ ?>